def fizzbuzz(n: int) -> list[str]:
    """Return the FizzBuzz sequence for integers 1 through n."""
    if n < 1:
        return []

    result = []
    for i in range(1, n + 1):
        if i % 3 == 0 and i % 5 == 0:
            result.append("FizzBuzz")
        elif i % 3 == 0:
            result.append("Fizz")
        elif i % 5 == 0:
            result.append("Buzz")
        else:
            result.append(str(i))

    return result


if __name__ == "__main__":
    print(fizzbuzz(15))
